type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };

export function processScenario(scenario: { customer: unknown; steps: unknown[] }): unknown {
  const results: unknown[] = [];
  for (const step of scenario.steps as { op: string; items?: Item[] }[]) {
    if (step.op === "quote") {
      const items = step.items ?? [];
      let total = 0;
      for (const item of items) {
        if (item.type === "sword") total += 100;
      }
      results.push({ premium: total + 5 });
    }
  }
  return { results };
}

