type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };

function basePremium(itemType: string): number {
  if (itemType === "sword") return 100;
  if (itemType === "amulet") return 60;
  if (itemType === "staff") return 80;
  if (itemType === "potion") return 40;
  if (itemType === "rune" || itemType === "moonstone") return 25;
  return 0;
}

function isComponent(itemType: string): boolean {
  return itemType === "rune" || itemType === "moonstone";
}

export function processScenario(scenario: { customer: unknown; steps: unknown[] }): unknown {
  const results: unknown[] = [];
  for (const step of scenario.steps as { op: string; items?: Item[] }[]) {
    if (step.op === "quote") {
      const items = step.items ?? [];
      const counts: Record<string, number> = {};
      const mainItems: Item[] = [];

      let policyBase = 0;
      let itemSurcharges = 0;

      for (const item of items) {
        if (isComponent(item.type)) {
          counts[item.type] = (counts[item.type] ?? 0) + 1;
        } else {
          mainItems.push(item);
        }
      }

      for (const type of Object.keys(counts)) {
        if (counts[type] === 3) policyBase += 60;
        else policyBase += counts[type] * 25;
      }

      for (const item of mainItems) {
        const base = basePremium(item.type);
        policyBase += base;
        if (item.cursed) itemSurcharges += base * 0.5;
        if ((item.enchantment ?? 0) >= 5) itemSurcharges += base * 0.3;
      }

      results.push({ premium: policyBase + itemSurcharges + 5 });
    }
  }
  return { results };
}

