type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };

export function processScenario(scenario: { customer: unknown; steps: unknown[] }): unknown {
  const results: unknown[] = [];
  for (const step of scenario.steps as { op: string; items?: Item[] }[]) {
    if (step.op === "quote") {
      const items = step.items ?? [];
      let total = 0;
      const counts: Record<string, number> = {};
      for (const item of items) {
        if (item.type === "rune" || item.type === "moonstone") {
          counts[item.type] = (counts[item.type] ?? 0) + 1;
        } else {
          if (item.type === "sword") total += 100;
          if (item.type === "amulet") total += 60;
          if (item.type === "staff") total += 80;
          if (item.type === "potion") total += 40;
        }
      }
      for (const type of Object.keys(counts)) {
        if (counts[type] === 3) total += 60;
        else total += counts[type] * 25;
      }
      results.push({ premium: total + 5 });
    }
  }
  return { results };
}

