input.content:
export type Customer = { yearsWithMHPCO: number };

export type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

export type QuoteStep = { op: "quote"; items: Item[] };
export type DamageEntry = { itemType: string; amount: number };
export type ClaimStep = {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: DamageEntry[] };
};
export type Step = QuoteStep | ClaimStep;

export type Scenario = { customer: Customer; steps: Step[] };

export type QuoteResult = { premium: number };
export type ClaimResult = { payout: number; remainingCap: number };
export type Result = QuoteResult | ClaimResult;

type InsuredItem = {
  type: string;
  value: number;
  material?: string;
  enchantment?: number;
};

type Policy = {
  items: InsuredItem[];
  insuranceSum: number;
  cap: number;
  remainingCap: number;
};

const MAIN_ITEMS: Record<string, { value: number; premium: number }> = {
  sword: { value: 1000, premium: 100 },
  amulet: { value: 600, premium: 60 },
  staff: { value: 800, premium: 80 },
  potion: { value: 400, premium: 40 },
};

const COMPONENTS: Record<string, { value: number; premium: number }> = {
  rune: { value: 250, premium: 25 },
  moonstone: { value: 250, premium:25 },
};

function isComponent(type: string): boolean {
  return type in COMPONENTS;
}

function isKnownType(type: string): boolean {
  return type in MAIN_ITEMS || isComponent(type);
}

export function processScenario(scenario: Scenario): { results: Result[] } {
  const results: Result[] = [];
  const policies: (Policy | undefined)[] = [];
  let quoteCount = 0;

  for (const step of scenario.steps) {
    if (step.op === "quote") {
      const items = step.items;
      for (const item of items) {
        if (!isKnownType(item.type)) {
          throw new Error(`Unknown item type: ${item.type}`);
        }
      }

      const counts: Record<string, number> = {};
      const main: Item[] = [];
      for (const item of items) {
        if (isComponent(item.type)) {
          counts[item.type] = (counts[item.type] ?? 0) + 1;
        } else {
          main.push(item);
        }
      }

      let base = 0;
      for (const type of Object.keys(counts)) {
        if (counts[type] === 3) base += 60;
        else base += counts[type] * COMPONENTS[type].premium;
      }
      for (const item of main) {
        base += MAIN_ITEMS[item.type].premium;
      }

      let surcharges = 0;
      for (const item of main) {
        const b = MAIN_ITEMS[item.type].premium;
        if (item.cursed) surcharges += b * 0.5;
        if ((item.enchantment ?? 0) >= 5) surcharges += b * 0.3;
      }

      let policyWide = 0;
      if (scenario.customer.yearsWithMHPCO >= 2) policyWide -= 0.2 * base;
      policyWide += 0.1 * base;
      if (quoteCount > 0) policyWide -= 0.15 * base;

      const total = base + surcharges + policyWide;
      const premium = Math.ceil(total + 5);

      const insuredItems: InsuredItem[] = [];
      let insuranceSum = 0;
      for (const item of items) {
        const value =
          MAIN_ITEMS[item.type]?.value ?? COMPONENTS[item.type].value;
        insuranceSum += value;
        insuredItems.push({ type: item.type, value, material: item.material, enchantment: item.enchantment });
      }
      const cap = 2 * insuranceSum;

      policies[results.length] = {
        items: insuredItems,
        insuranceSum,
        cap,
        remainingCap: cap,
      };
      results.push({ premium });
      quoteCount++;
    } else if (step.op === "claim") {
      const policy = policies[step.policy];
      if (!policy) {
        throw new Error(`Policy not found at step ${step.policy}`);
      }

      for (const damage of step.incident.damages) {
        if (!isKnownType(damage.itemType)) {
          throw new Error(`Unknown item type: ${damage.itemType}`);
        }
        if (damage.amount < 0) {
          throw new Error(`Negative damage amount: ${damage.amount}`);
        }
        const insuredOfType = policy.items.filter((i) => i.type === damage.itemType).length;
        if (insuredOfType === 0) {
          throw new Error(`Item not part of policy: ${damage.itemType}`);
        }
      }

      const damagedCounts: Record<string, number> = {};
      for (const damage of step.incident.damages) {
        damagedCounts[damage.itemType] = (damagedCounts[damage.itemType] ?? 0) + 1;
      }
      for (const type of Object.keys(damagedCounts)) {
        const insuredOfType = policy.items.filter((i) => i.type === type).length;
        if (damagedCounts[type] > insuredOfType) {
          throw new Error(`More damage entries for ${type} than insured`);
        }
      }

      let payout = 0;
      for (const damage of step.incident.damages) {
        const item = policy.items.find((i) => i.type === damage.itemType && i.enchantment !== undefined);
        const info = isComponent(damage.itemType) ? null : MAIN_ITEMS[damage.itemType];
        let reimbursement = damage.amount;
        if (info && (item?.enchantment ?? 0) >= 8) {
          reimbursement = damage.amount * 0.5;
        } else if (item?.material === "dragon") {
          reimbursement = damage.amount;
        }
        payout += Math.max(0, reimbursement - 100);
      }

      payout = Math.min(payout, policy.remainingCap);
      policy.remainingCap -= payout;

      results.push({ payout, remainingCap: policy.remainingCap });
    }
  }

  return { results };
}

